'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var join = require( 'path' ).join;
var logger = require( 'debug' );
var exists = require( '@stdlib/fs/exists' ).sync;
var writeFile = require( '@stdlib/fs/write-file' ).sync;
var pkgNames = require( '@stdlib/_tools/pkgs/names' );
var namespace = require( '@stdlib/namespace' );
var pkg2alias = require( '@stdlib/namespace/pkg2alias' );
var pkg2related = require( '@stdlib/namespace/pkg2related' );


// VARIABLES //

var debug = logger( 'namespace:packages:build' );

// Root of the monorepo lib directory:
var LIB_DIR = resolve( __dirname, '..', '..', '..', '..', '..' );

// Output file paths:
var OUTPUT_JSON = resolve( __dirname, '..', 'data', 'data.json' );
var ROOT_JSON = resolve( LIB_DIR, '..', 'pkg-catalog.json' );


// FUNCTIONS //

/**
* Builds a lookup mapping package paths to their namespace type.
*
* @private
* @returns {Object} mapping from package path to type string
*/
function buildTypeIndex() {
	var entries;
	var out;
	var i;

	entries = namespace();
	out = {};
	for ( i = 0; i < entries.length; i++ ) {
		out[ entries[ i ].path ] = entries[ i ].type;
	}
	return out;
}

/**
* Returns the description for a package by reading its package.json.
*
* @private
* @param {string} pkgDir - absolute path to the package directory
* @returns {string} package description, or empty string if not found
*/
function getDescription( pkgDir ) {
	var pkgJSON;
	var fpath;

	fpath = join( pkgDir, 'package.json' );
	if ( !exists( fpath ) ) {
		return '';
	}
	try {
		pkgJSON = require( fpath ); // eslint-disable-line stdlib/no-dynamic-require
		return pkgJSON.description || '';
	} catch ( err ) {
		debug( 'WARNING: unable to read package.json for %s: %s', pkgDir, err.message );
		return '';
	}
}

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var typeIndex;
	var related;
	var pkgDir;
	var names;
	var fopts;
	var alias;
	var json;
	var type;
	var pkg;
	var tmp;
	var i;

	debug( 'Enumerating all packages...' );
	names = pkgNames.sync();
	debug( 'Found %d packages.', names.length );

	debug( 'Building namespace type index...' );
	typeIndex = buildTypeIndex();

	debug( 'Filtering out internal tooling packages...' );
	tmp = [];
	for ( i = 0; i < names.length; i++ ) {
		if ( names[ i ].indexOf( '@stdlib/_tools' ) === -1 ) {
			tmp.push( names[ i ] );
		}
	}
	names = tmp;
	debug( '%d packages after filtering.', names.length );

	debug( 'Building package catalog...' );
	json = {};
	for ( i = 0; i < names.length; i++ ) {
		pkg = names[ i ];
		pkgDir = join( LIB_DIR, 'node_modules', pkg );

		alias = pkg2alias( pkg );
		related = pkg2related( pkg );
		type = typeIndex[ pkg ] || '';

		json[ pkg ] = {
			'description': getDescription( pkgDir ),
			'alias': alias || '',
			'type': type,
			'related': related || [],
			'hasCliTool': exists( join( pkgDir, 'bin', 'cli' ) ),
			'hasNativeAddon': exists( join( pkgDir, 'binding.gyp' ) ),
			'hasWasm': exists( join( pkgDir, 'src', 'main.wasm' ) )
		};
	}

	debug( 'Writing to JSON file...' );
	fopts = {
		'encoding': 'utf8'
	};
	writeFile( OUTPUT_JSON, JSON.stringify( json ) + '\n', fopts );

	debug( 'Writing root-level pkg-catalog.json...' );
	writeFile( ROOT_JSON, JSON.stringify( json, null, '  ' ) + '\n', fopts );

	debug( 'Done. Wrote %d entries.', names.length );
	console.log( 'Generated package catalog with %d entries.', names.length ); // eslint-disable-line no-console
}


// MAIN //

main();
